#include <limits>

using namespace std;

int n;
vector<pair<int, int>> items; // Pair of weight and strength
vector<int> bestIndex;
int bestG;

void solve(int k, int usedMask, vector<int>& index, int g, int sumW) {
    if (k == n) {
        if (g < bestG) {
            bestG = g;
            bestIndex = index;
        }
        return;
    }
    for (int i = 0; i < n; ++i) {
        if (usedMask & (1 << i)) continue; // Check if the item is already used
        if (items[i].second >= sumW) {
            index[k] = i;
            solve(k + 1, usedMask | (1 << i), index, g + (n - k) * items[i].first, sumW + items[i].first);
        }
    }
}

int main() {
    for (;;) {
        cin >> n;
        if (n == 0) return 0;

        items.resize(n);
        vector<string> name(n);
        for (int i = 0; i < n; ++i)
            cin >> name[i] >> items[i].first >> items[i].second;

        bestG = numeric_limits<int>::max(); // Using numeric_limits for clarity
        vector<int> index(n);
        solve(0, 0, index, 0, 0);
        for (int i = n - 1; i >= 0; --i)
            cout << name[bestIndex[i]] << endl;
    }
}

