    if (g >= bestG) return; // Early exit if the current score is already worse
    if (k == n) {
        bestG = g;
        bestIndex = index;
        return;
    }
    for (int i = 0; i < n; ++i) {
        if (used[i]) continue;
        used[i] = true;
        if (s[i] >= sumW) {
            index[k] = i;
            solve(k + 1, index, g + (n - k) * w[i], sumW + w[i]);
        }
        used[i] = false;
    }
}

int main() {
    for (;;) {
        cin >> n;
        if (n == 0) return 0;

        vector<string> name(n);
        w.resize(n);
        s.resize(n);
        used.resize(n, false);
        vector<int> index(n);

        for (int i = 0; i < n; ++i)
            cin >> name[i] >> w[i] >> s[i];

        bestG = numeric_limits<int>::max();
        solve(0, index, 0, 0);
        for (int i = n - 1; i >= 0; --i)
            cout << name[bestIndex[i]] << endl;
    }
}

